Definition art_rel_shw (spb : Z) (e : art_rel) : Z * Z :=
  match e with
  | REP c w d _ n => (SB + (spb + c * 2 ^ 32 + 16 * w + d + 16) / 8, (n + 7) / 8 * 8 / 8)
  | RES mb ms _ _ _ => (SB + mb / 8, ms / 8)
  | REB _ => (0, 0)
  end.

